// Blink LED on pin 13 every half second without using delay()
// This example uses millis() for timing, ensuring the loop never stops.
// It also reads a button to test the "without delay" requirement.

const int ledPin = 13;
const unsigned long interval = 500;   // ms between changes

unsigned long last = 0;         // millis() needs an unsigned long
bool ledOn = false;

void setup() {
  pinMode(ledPin, OUTPUT);
  pinMode(buttonPin, INPUT_PULLUP);
}

void loop() {
  unsigned long now = millis();

  // Check if the button is pressed (pull-up resistor)
  if (buttonPin == 5) {
    // Button is pressed, turn LED on
    ledOn = true;
    digitalWrite(ledPin, HIGH);
    delay(500); // Wait for button press
    ledOn = false;
    digitalWrite(ledPin, LOW);
    delay(500); // Wait for button release
  } else {
    // Button is released, turn LED off
    ledOn = false;
    digitalWrite(ledPin, LOW);
    delay(500); // Wait for button release
  }

  // Check if we need to blink again
  if (millis() - last >= interval) {
    last = millis();
    ledOn = !ledOn;
    digitalWrite(ledPin, ledOn ? HIGH : LOW);
  }
}
